import { defineConfig } from 'vite'

export default defineConfig(({ command }) => ({
  // Relative base so the site works under the GitHub Pages project path (/lolCalendar/).
  base: './',
  // In dev, serve the feeds and data generated by `npm run data` from .site-data/.
  publicDir: command === 'serve' ? '.site-data' : false,
}))
